library(tidyverse)
library(lubridate)
library(moments)
example<-read.csv("C:/Users/hp/Desktop/Economics/ecommerce_dataset_updated.csv")
glimpse(example)
example<-example%>%rename(Price=Price..Rs..,Discount=Discount....,Final_Price=Final_Price.Rs..)
colSums(is.na(example))
summary(example$Price)
skewness(example$Price)
ggplot(example,aes(x=Price))+geom_histogram(fill="steelblue",color="white",bins = 30)+geom_vline(aes(xintercept = mean(Price,na.rm=TRUE)),color="red",linetype="dashed",linewidth=1)+geom_vline(aes(xintercept = median(Price,na.rm=TRUE)),color="green",linetype="solid",linewidth=1)+labs(title = "PPD",subtitle = "medain=green|mean=red")
summary(example$Final_Price)
skewness(example$Final_Price)
ggplot(example,aes(x=Final_Price))+geom_histogram(fill = "steelblue",colour = "white",bins=30)+geom_vline(aes(xintercept = mean(Final_Price,na.rm=TRUE)),color="red",linetype="dashed",linewidth=1)+geom_vline(aes(xintercept = median(Final_Price,is.na=TRUE)),color="green",linetype="solid",linewidth=1)
Category_sales<-example%>%group_by(Category)%>%summarise(Total_Order=n(),Total_Revenue=sum(Final_Price,na.rm = TRUE))%>%mutate(Sale_Share=round((Total_Revenue/sum(Total_Revenue)*100)))%>%arrange(desc(Total_Revenue))
ggplot(Category_sales,aes(x=reorder(Category,Total_Revenue),y=Total_Revenue))+geom_col(fill="steelblue")+coord_flip()+labs(title = "Total sales by product category",x="category",y="Total_Revenue")+theme_minimal()
Method<-example%>%group_by(Payment_Method)%>%summarise(Total_order=n(),Total_Revenue=sum(Final_Price,na.rm = TRUE))%>%arrange(desc(Total_Revenue))
ggplot(Method,aes(x=reorder(Payment_Method,Total_Revenue),y=Total_Revenue))+geom_col(fill="steelblue")+coord_flip()+labs(title = "Total sales by payment method",x="payment method",y="Total Revenue")+theme_minimal()
Monthly_Sales<-example%>%mutate(Date=dmy(Purchase_Date))%>%mutate(Month=floor_date(Date,"month"))%>%group_by(Month)%>%summarise(Total_Order=n(),Total_Revenue=sum(Final_Price,na.rm = TRUE))%>%arrange(Month)
Monthly_Sales
ggplot(Monthly_Sales,aes(x=Month,y=Total_Revenue))+geom_line(color="steelblue",linewidth=1.2)+geom_point(color="darkred",size=2.5)+scale_x_date(date_labels = "%b%Y",date_breaks = "1 month")+expand_limits(y=0)+labs(title = "Monthly Sales Trend",x="Month",y="Total Revenue")+theme_minimal()+theme(axis.text.x = element_text(angle = 45,hjust = 1))
discount_analysis<-example%>%mutate(Discount_Bracket=case_when(Discount<=10~"1.Low(0-10%)",Discount<=20~"2.Mediom(10-20%)",TRUE~"3.High(>20)"))%>%group_by(Category,Discount_Bracket)%>%summarise(Total_Order=n(),Avg_Original_Price=round(mean(Price,na.rm=TRUE)),Avg_Final_Price=round(mean(Final_Price,na.rm=TRUE)),Total_Revenue=sum(Final_Price,na.rm = TRUE))%>%arrange(Category,desc(Total_Order))
ggplot(discount_analysis,aes(x=Category,y=Total_Revenue,fill=Discount_Bracket))+geom_col(position = "dodge")+labs(title = "Total Revenue bu Category and Discount Bracket",x="Product Category",y="Total Revenue",fill="Discount Level")+theme_minimal()+theme(axis.text.x = element_text(angle=45,hjust=1))
ggplot(discount_analysis,aes(x=Category,y=Total_Revenue,fill=Discount_Bracket))+geom_col(position = "fill")+scale_fill_brewer(palette = "Blues")+labs(title = "Total Revenue bu Category and Discount Bracket",x="Product Category",y="Total Revenue",fill="Discount Level")+theme_minimal()+theme(axis.text.x = element_text(angle=45,hjust=1))
